<?php $pageTitle='Customers';$cssPath='../css/style.css';$homePath='../index.php';$roomsPath='rooms.php';$contactPath='../contact.php';$bookingsPath='bookings.php';$logoutPath='logout.php';require '../db/connection.php';require '../includes/functions.php';require_admin();$customers=$pdo->query("SELECT u.*,COUNT(b.id) bookings FROM users u LEFT JOIN bookings b ON b.user_id=u.id GROUP BY u.id ORDER BY u.created_at DESC")->fetchAll();include '../includes/header.php';?><section class="section"><div class="container"><span class="eyebrow">Guest relations</span><h1>Registered customers</h1><div class="panel table-wrap"><table class="table"><tr><th>Name</th><th>Email</th><th>Phone</th><th>Bookings</th><th>Joined</th></tr><?php foreach($customers as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['email'])?></td><td><?=e($c['phone'])?></td><td><?=e($c['bookings'])?></td><td><?=e(date('d M Y',strtotime($c['created_at'])))?></td></tr><?php endforeach;?></table></div></div></section><?php include '../includes/footer.php';?>
